&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;읽기 시간: 22 minutes&lt;/div&gt;
&lt;p&gt;사람들은 종종 내 AI 사용량이 얼마나 비용이 드는지 자주 묻는다. 저는 &#39;한 달에 20유로&amp;#8217;라고 답하고, 사람들은 놀란 눈으로 저를 바라본다. 그렇다면 오늘, 저는 여러분께 검은 상자를 열어 보이겠다. 이 글은 나의 73일간의 바이브 코딩에 대한 종합 감사이다: OpenCode의 SQLite 데이터베이스에서 데이터를 추출하는 방법론, 테이블을 쿼리하는 SQL 코드, 그리고 시장의 모든 공급업체 — 서양과 중국을 포함한 — 에 대한 포괄적인 비교. 결과가 너무나 비대칭적이어서 나는 계산을 세 번 확인해야 했다.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;똑&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_스택_이해하기_누가_무엇을_하는가&quot;&gt;스택 이해하기: 누가 무엇을 하는가?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;수자에 뛰어들기 전에 아키텍처를 명확히 합시다. 내 설정에는 세 가지 다른 행위자가 있으며, 그들을 혼동하지 않는 것이 중요합니다:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title 내 스택 LLM의 세 명의 배우
left to right direction

actor &quot;저 (개발자)&quot; as Dev

package &quot;오픈코드
(github.com/anomalyco/opencode)&quot; as OC {
  rectangle &quot;vibe coding의 CLI
오픈 소스, 무료&quot; as CLI
  note right of CLI
    C&#39;est l&#39;outil que j&#39;utilise
    pour coder avec des agents IA.
    Il ne fournit AUCUN modèle.
    C&#39;est un terminal + un orchestrateur.
  end note
}

package &quot;Ollama (로컬 설치)&quot; as OL {
  rectangle &quot;추론 클라이언트
내 머신에 설치됨&quot; as Client
  note right of Client
    C&#39;est le logiciel qui fait tourner
    les modèles. Il peut les exécuter
    en local OU les déléguer au cloud
    selon le tag (:cloud).
    Il s&#39;authentifie via clé SSH.
  end note
}

package &quot;Ollama 클라우드
(ollama.com)&quot; as OCloud {
  rectangle &quot;클라우드 추론 서비스
프로 구독: 20€/월&quot; as Cloud
  note right of Cloud
    C&#39;est le fournisseur d&#39;inférence.
    Mes modèles avec le tag :cloud
    sont exécutés sur LEURS serveurs.
    L&#39;abonnement Pro donne accès
    à des quotas supérieurs.
  end note
}

Dev --&amp;gt; CLI : &quot;프롬프트를 입력합니다&quot;
CLI --&amp;gt; Client : &quot;이 모델을 불러&quot;
Client --&amp;gt; Cloud : &quot;SSH 키 + 요청
(모델 :cloud)&quot;
Client --&amp;gt; Client : &quot;로컬 실행
(클라우드가 없는 모델)&quot;

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;❗&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;OpenCode는 모델 제공자가 아닙니다.&lt;/strong&gt;이것은 오픈 소스 CLI입니다 (&lt;a href=&quot;https://github.com/anomalyco/opencode&quot;&gt;github.com/anomalyco/opencode&lt;/a&gt;) AI 에이전트를 오케스트레이션합니다. 구독을 판매하지 않으며, 추론을 제공하지 않습니다. 이것은의 동등물이다`git`버전 관리를 위한: 도구이지 서비스가 아닙니다. &lt;strong&gt;Ollama Cloud는 추론 제공업체입니다.&lt;/strong&gt;내 로컬 Ollama 설치는 &lt;strong&gt;client&lt;/strong&gt; 역할을 합니다 — 고유한 SSH 키(Device Key)를 통해 Ollama 서버에 인증하고, 태그가 지정된 모델의 실행을 그들에게 위임합니다.&lt;code&gt;:cloud&lt;/code&gt;. 프로 구독(20유로/월)은 상위 할당량을 해제하고 Docker를 통해 동일한 머신에서 여러 계정을 통합할 수 있습니다.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_서론_왜_감사가_필요한가&quot;&gt;서론: 왜 감사가 필요한가?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;두 달 전, 저는 로컬 Ollama 설치에서 모델을 무료로 사용하고 있었습니다. 그리고 저는 월 20유로에 첫 번째 Ollama Cloud Pro 구독을 시작했습니다. 이로 인해 클라우드 모델(태그가 있는`:cloud`) 제공업체를 통해`ollama-cloud`. 두 번째 구독이 한 달 후에 이어졌습니다, 별도의 Docker 인스턴스에서 자신의 계정과 자신의 SSH 키를 가진 — &lt;a href=&quot;0120_cumuler_deux_abonnements_ollama_pro_docker_post.html&quot;&gt;구독 누적에 대한 내 글&lt;/a&gt;에서 설명한 누적 방법.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;제가 고민하던 질문: &lt;strong&gt;이 20유로가 월마다 타당한가요 ?&lt;/strong&gt; 직감으로가 아니라. 숫자로.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;답변하기 위해서는 정확한 데이터가 필요했습니다. 추정이 아닙니다. 평균이 아닙니다. 나의 실제 &lt;strong&gt;소비&lt;/strong&gt;, 토큰 단위로, 모델 단위로, 세션 단위로.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;그리고 OpenCode — CLI — 는 이를 모두 SQLite 데이터베이스에 저장합니다.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_opencode_데이터베이스_금광&quot;&gt;OpenCode 데이터베이스: 금광&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;OpenCode는 세션 기록 전반를 SQLite 파일 안에 위치해 있는`~/.local/share/opencode/opencode.db`. La mienne pèse 660 Mo pour 73 jours d&amp;#8217;utilisation — une base de données de production tout à fait respectable.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;$ ls -lh ~/.local/share/opencode/opencode.db
-rw-r--r-- 1 cheroliv cheroliv 660M mai 18 12:25 opencode.db&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_스키마&quot;&gt;스키마&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;베이스에는 약 20개의 테이블이 있지만, 그중 세 개는 우리 감사에 매우 중요합니다:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam defaultFontSize 12

title 간소화된 스키마 — OpenCode SQLite
entity &quot;세션&quot; as S {
  * id : TEXT
  --
  * model : TEXT (JSON)
  * cost : REAL
  * tokens_input : INTEGER
  * tokens_output : INTEGER
  * tokens_reasoning : INTEGER
  * tokens_cache_read : INTEGER
  * tokens_cache_write : INTEGER
  * time_created : INTEGER
  * project_id : TEXT
}

entity &quot;메시지&quot; as M {
  * id : TEXT
  --
  * session_id : TEXT &amp;lt;&amp;lt;FK&amp;gt;&amp;gt;
  * data : TEXT (JSON)
  * time_created : INTEGER
}

entity &quot;프로젝트&quot; as P {
  * id : TEXT
  --
  * worktree : TEXT
  * name : TEXT
}

S ||--o{ M : &quot;세션 아이디&quot;
S }o--|| P : &quot;프로젝트_ID&quot;

note right of S
  La table session agrège
  tokens + coût + modèle.
  C&#39;est notre point d&#39;entrée
  principal.
end note

note right of M
  Les messages individuels.
  Le champ data contient
  le modèle utilisé (format JSON)
  même si la session change
  de modèle en cours de route.
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;테이블`session`전역 감사에 적합합니다 : 각 세션은 집계된 토큰 수, 사용된 모델, 그리고 비용을 가지고 있습니다. 필드`model`원시 JSON입니다 :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
  &quot;id&quot;: &quot;deepseek-v4-pro:cloud&quot;,
  &quot;providerID&quot;: &quot;ollama-cloud&quot;,
  &quot;variant&quot;: &quot;default&quot;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;❗&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;필드`cost`OpenCode 데이터베이스에서는 *외부 API 요금*만 반영됩니다. 즉, API 키(Google Gemini, OpenAI 등)를 통해 사용량 기준으로 지불된 비용만 표시됩니다. Ollama을 통한 호출 — 로컬이든 Ollama Cloud Pro를 통해든 — 은 표시됩니다.`cost=0`비용이 정액제(구독)이기 때문에, 토큰당이 아닙니다. 이러한 호출의 실제 비용은 월간 구독료입니다.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_추출_코드&quot;&gt;추출 코드&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;설치할 필요가 없습니다. Node.js 22+는 실험용 SQLite 모듈을 포함합니다 (&lt;code&gt;node:sqlite&lt;/code&gt;) 완벽하게 작동합니다. 다음은 저에게 모든 것을 준 스크립트입니다:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-javascript hljs&quot; data-lang=&quot;javascript&quot;&gt;const { DatabaseSync } = require(&#39;node:sqlite&#39;);
const db = new DatabaseSync(
  `${process.env.HOME}/.local/share/opencode/opencode.db`,
  { readonly: true }
);

// 1. Statistiques globales
const global = db.prepare(`
  SELECT
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(tokens_reasoning) as total_reasoning,
    SUM(tokens_cache_read) as total_cache_read,
    SUM(cost) as total_cost
  FROM session
`).get();

// 2. Ventilation par modèle et fournisseur
const byModel = db.prepare(`
  SELECT
    json_extract(model, &#39;$.id&#39;) as model_id,
    json_extract(model, &#39;$.providerID&#39;) as provider,
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(cost) as total_cost
  FROM session
  WHERE model IS NOT NULL
  GROUP BY model_id, provider
  ORDER BY SUM(tokens_input) DESC
`).all();

// 3. Par mois
const monthly = db.prepare(`
  SELECT
    strftime(&#39;%Y-%m&#39;, datetime(time_created/1000, &#39;unixepoch&#39;)) as month,
    COUNT(*) as sessions,
    SUM(tokens_input) as total_input,
    SUM(tokens_output) as total_output,
    SUM(cost) as total_cost
  FROM session
  WHERE time_created IS NOT NULL
  GROUP BY month
  ORDER BY month
`).all();

// 4. Messages par modèle (détection des changements intra-session)
const msgByModel = db.prepare(`
  SELECT
    json_extract(m.data, &#39;$.model.providerID&#39;) as provider,
    json_extract(m.data, &#39;$.model.modelID&#39;) as model_id,
    COUNT(*) as messages
  FROM message m
  WHERE json_extract(m.data, &#39;$.model&#39;) IS NOT NULL
  GROUP BY provider, model_id
  ORDER BY COUNT(*) DESC
`).all();

console.log({ global, byModel, monthly, msgByModel });
db.close();&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;ℹ️&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;플래그`--experimental-sqlite`Node.js 22.x에서 필요합니다. Node.js 24+에서는 모듈이 안정적이며 더 이상 플래그가 필요하지 않습니다.&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_결과_73일_소비&quot;&gt;결과: 73일 소비&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_전체_보기&quot;&gt;전체 보기&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 33.3334%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
