  rectangle &quot;🏆 Ollama Max
$100/월&quot; as max
  rectangle &quot;🏆 전용 클라우드 GPU
$2-4/h&quot; as dedicated
  rectangle &quot;Modal / Together AI\n서버리스&quot; as serverless
}

package &quot;필수 에어 갭&quot; #FFCDD2 {
